CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.investment_metrics
COMMENT 'The asset side: market value, book cost, unrealised gain and investment income by asset class and legal entity. Query with MEASURE(); constrain currency_code.'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_investment.investment_holding

joins:
  - name: asset_class_ref
    source: lr_serverless_aws_us_catalog.bricksurance_reference.asset_class
    on: source.asset_class_code = asset_class_ref.asset_class_code

dimensions:
  - name: asset_class
    expr: asset_class_ref.label
  - name: asset_class_code
    expr: source.asset_class_code
  - name: legal_entity_id
    expr: legal_entity_id
  - name: currency_code
    expr: currency_code

measures:
  - name: market_value
    expr: SUM(market_value)
  - name: book_cost
    expr: SUM(book_cost)
  - name: unrealised_gain
    expr: SUM(market_value) - SUM(book_cost)
  - name: holding_count
    expr: COUNT(*)
$$;
